  bdDriveV: 1.00,
  bdAsym: 0.0,
  sdDriveV: 0.90,
  tomDriveV: 1.80,
  bdWaveTriMix: 0.105,
  bdWaveDrive: 1.18,

  // [SCHALTPLAN] ATTACK ist ein Spannungsteiler, kein Gain-Regler:
  // R45 4.7K speist den Knoten, R56 330 gegen Masse, VR3 500(B) darueber.
