  bdAtkNoiseLp: 420,
  bdAtkNoiseMix: 1.254,
  bdDcHp: 24,
  bdDrive: 0.60,
  bdSat: 1.10,

  // SNARE DRUM: the service notes explicitly describe two triangle VCOs,
  // phase reset by TRIG, a ~20 ms pitch CV, independent VCAs, and shared
