  // durch den Werkstrimmer cal.sd1F (1,036) geteilt, damit die Tabelle am
  // Ausgang exakt die gemessenen Werte ergibt
  sdF1Table: [131.0, 147.1, 206.5, 234.2],
  // [GEMESSEN] VCO2 liegt bei allen vier TUNE-Stellungen auf dem
