  sdF2Ratio: 1.435,
  sdF1: 171.0,
  sdF2: 326.0,
  sdTuneOct: 0.545,
  sdPitchDepth: 0.55,
  // [SCHALTPLAN S. 11] ENV1 der Snare ist C66 0.01uF, entladen ueber R248
