  sdBodyTau1: 0.0155,
  sdBodyTau2: 0.0090,
  sdBodyMix1: 1.08,
  sdBodyMix2: 0.80,
  sdBodyTri1: 0.14,
  sdBodyTri2: 0.17,
  sdBodyLp: 1400,
  // Two real snappy branches: a short quiet burst and the main path.
  // The main envelope has an initial ~24 ms plateau, then TONE sets decay.
  // Q47/Q48 sind ebenfalls Swing-Type-VCAs.  Whittle beschreibt sie genau:
  // unterhalb rund 0,4 V an der Basis kommt nichts mehr durch, oberhalb ~8 V
