  // Tabelle: V = 0..14 in 0.25-V-Schritten, normiert.
  bodyVcaTable: [0.0000,0.0885,0.0926,0.0969,0.1014,0.1061,0.1110,0.1162,0.1215,0.1272,0.1330,0.1392,0.1456,0.1524,0.1594,0.1668,0.1745,0.1826,0.1911,0.1999,0.2092,0.2189,0.2290,0.2397,0.2508,0.2624,0.2745,0.2872,0.3006,0.3145,0.3291,0.3443,0.3602,0.3769,0.3944,0.4127,0.4318,0.4517,0.4728,0.4947,0.5174,0.5416,0.5666,0.5928,0.6205,0.6487,0.6793,0.7104,0.7436,0.7779,0.8140,0.8517,0.8911,0.9340,0.9801,1.0000,1.0000],
  sdVcaTable: [0.0000,0.0065,0.0072,0.0079,0.0087,0.0095,0.0105,0.0116,0.0127,0.0140,0.0154,0.0170,0.0187,0.0206,0.0226,0.0249,0.0274,0.0302,0.0332,0.0366,0.0403,0.0443,0.0488,0.0537,0.0591,0.0651,0.0717,0.0789,0.0869,0.0956,0.1052,0.1159,0.1277,0.1407,0.1548,0.1702,0.1877,0.2068,0.2274,0.2504,0.2761,0.3035,0.3344,0.3685,0.4046,0.4468,0.4910,0.5414,0.5958,0.6560,0.7227,0.7949,0.8777,0.9676,1.0000,1.0000,1.0000],
  // Entladung jetzt HERGELEITET: tau = 0.47uF * (220K + TONE*500K)
