  sdNoiseEnvC: 0.47e-6,
  sdNoiseEnvRFix: 220000,
  sdNoiseEnvRPot: 330000,
  sdNoiseEnvPeakV: 13.5,
  sdNoiseTailTauMin: 0.012,
  sdNoiseTailTauMax: 0.028,
  sdNoiseMainHold: 0.0,
  sdNoiseMainTauMin: 0.0047,
  sdNoiseMainTauMax: 0.0133,
  sdNoiseLp: 1150,
  sdNoiseHp: 4700,
  sdNoiseQ: 0.68,
  sdNoiseShortLp: 0.62,
  sdNoiseShortHp: 0.18,
  sdNoiseShortAmt: 0.22,
  sdNoiseMainLp: 0.30,
  sdNoiseMainHp: 0.58,
  sdNoiseMainAmt: 0.56,
  sdDrive: 0.86,
  sdSat: 1.05,

  // TOMS: each LT/MT/HT circuit contains three reset oscillator paths.
  // VCO1 is the middle/main component (slightly wave-shaped), VCO2 is the
  // lower body component, and VCO3 is the high, short attack component.
  // Ratios follow the 22n/33n/12n timing-capacitor relationship of the clone
