  tomTable: { lt: [61.68, 76.57, 105.95, 121.69],
              mt: [81.06, 96.55, 132.62, 151.73],
              ht: [93.26, 114.91, 154.68, 174.68] },
  tomPitchDepthTable: { lt: [0.382,0.303,0.293,0.286], mt: [0.478,0.396,0.310,0.278], ht: [0.408,0.385,0.301,0.277] },
  tomPitchTauTable: { lt: [0.0550,0.0549,0.0453,0.0443], mt: [0.0370,0.0404,0.0387,0.0389], ht: [0.0425,0.0386,0.0398,0.0392] },
  tomLt: 91.0,
  tomMt: 126.7,
  tomHt: 146.6,
  tomTuneOct: 0.752,
  tomPitchDepth: 0.11,
  tomPitchTau: 0.020,
  // [SCHALTPLAN S. 11] Die drei Tom-Oszillatoren sind Reset-Integratoren mit
  // UNTERSCHIEDLICHEN Zeitkondensatoren: IC19b C20 0.012uF, IC15b C18
  // 0.022uF, IC17b C19 0.033uF.  Daraus folgen die Verhaeltnisse direkt:
  //   0.022/0.012 = 1.8333     0.022/0.033 = 0.6667
  // KORREKTUR meiner letzten Aenderung: ich hatte VCO3 auf 2,96 gesetzt,
  // weil ich in der Referenz eine Linie beim 2,96-fachen fand.  Die ist
  // aber die DRITTE HARMONISCHE des Grundtons, nicht ein Oszillator -- sie
  // fehlte nur, weil das alte Modell einen fast reinen Sinus erzeugte.
  // Die gemessene Linie beim 1,87-fachen ist der echte VCO3.
  tomVco2Ratio: 0.6667,
  tomVco2RatioVoice: { lt: 0.6667, mt: 0.600, ht: 0.686 },
  tomVco3Ratio: 1.8333,
  tomVco3RatioVoice: { lt: 1.8333, mt: 1.58, ht: 1.70 },
  tomVco1Mix: 0.58,
  tomVco2Mix: 0.36,
  tomVco3Mix: 0.20,
  tomVco3MixVoice: { lt: 0.78, mt: 0.31, ht: 0.48 },
  // [GEMESSEN] Die Maschine hat ueber dem Grundton rund 20 % zweite und
  // 20 % dritte Harmonische; das Modell hatte 4 % bzw. 2 % -- praktisch ein
  // reiner Sinus, und genau das klingt duenn statt nach Trommelkoerper.
  // Die dritte kommt aus der Diodenrundung des Dreiecks (symmetrisch, also
