  tomAsym: 0.55,
  sdAsym: 0.38,
  sdEnvPeakV: 11.0,
  tomVco1TriMix: 0.28,
  tomAttackTau: 0.0055,
  // Der Rauschzweig hing bisher an derselben Huellkurve wie VCO3.  Als ich
  // die fuer VCO3 auf 120 ms verlaengert habe, wurde das Rauschen mit in die
  // Laenge gezogen -- daher der Zisch-Schlag, den die Maschine nicht hat.
  // Maschine: oberhalb 1 kHz nach 20 ms nur noch 0,02-0,03 % der Energie.
  tomNoiseTau: 0.0085,
  // Q19/Q20/Q21 sind Swing-Type-VCAs wie Q12 und Q50.  Die Maschine haelt
